// 1. Friendly checks before calling the server
if (!data.firstName || !data.lastName || !data.emailAddress || !data.password) {
  message.error("Please fill in all required fields.");
  return;
}
if (data.password !== data.confirmPassword) {
  message.error("Passwords do not match.");
  return;
}

// 2. Create the account
try {
  await http.post("/api/services/app/Registration/Register", {
    emailAddress: data.emailAddress,
    password: data.password,
    confirmPassword: data.confirmPassword,
    firstName: data.firstName,
    lastName: data.lastName,
    mobileNumber: data.mobileNumber,
    driversLicenceNumber: data.driversLicenceNumber,
    licenceExpiryDate: data.licenceExpiryDate
  });

  // 3. Success → go to login
  message.success("Account created! Please log in.");
  window.location.href = "/login";
} catch (e) {
  message.error(e?.response?.data?.error?.message ?? "Could not create your account");
}
